        self.expr = expr
        self.index = 0
        self.length = len(expr)

    def parse_expression(self):
        result = self.parse_term()
        while self.index < self.length:
            if self.peek() == '+':
                self.index += 1
                result += self.parse_term()
            elif self.peek() == '-':
                self.index += 1
                result -= self.parse_term()
            else:
                break
        return result

    def parse_term(self):
        result = self.parse_factor()
        while self.index < self.length:
            if self.peek() == '*':
                self.index += 1
                result *= self.parse_factor()
            elif self.peek() == '/':
                self.index += 1
                denominator = self.parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("division by zero")
                result /= denominator
            else:
                break
        return result

    def parse_factor(self):
        if self.peek() == '(':
            self.index += 1
            result = self.parse_expression()
            if self.peek() == ')':
                self.index += 1
                return result
            else:
                raise ValueError("Mismatched parentheses")
        return self.parse_number()

    def parse_number(self):
        start = self.index
        if self.peek() in '+-':
            self.index += 1
        while self.index < self.length and (self.peek().isdigit() or self.peek() == '.'):
