    def __init__(self, expr):
        self.expr = expr
        self.pos = 0
        self.current_char = self.expr[self.pos] if self.expr else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char in ' ':
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.expr()
            self.advance()  # Skip ')'
            return result
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.number()
        else:
            self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in "*/":
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_char is not None and self.current_char in "+-":
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result

